begin;set local search_path=public,extensions;select plan(14);
select is(private.minimize_assistance_input('CNIE n° AB 123456'),'CNIE n° [CIN]','spaced CNIE variant minimized');
select is(private.minimize_assistance_input('Passeport n° XY 987654'),'Passeport n° [PASSPORT]','spaced passport variant minimized');
select is(private.minimize_assistance_input('JALIL MANSOURI;'),'[NAME];','unlabelled all-caps name minimized');
select is(private.minimize_assistance_input('جليل المنصوري؛'),'[NAME]؛','Arabic unlabelled name remains minimized');
select ok(not has_function_privilege('authenticated','private.run_assistance_input_purge_cycle(integer)','EXECUTE'),'authenticated cannot execute autonomous worker');
select ok(not has_function_privilege('service_role','private.run_assistance_input_purge_cycle(integer)','EXECUTE'),'service role cannot bypass the public worker contract');
select ok(not exists(select 1 from pg_extension where extname='pg_cron')or exists(select 1 from cron.job where jobname='matricia-assistance-input-purge-v1'and active),'versioned cron job exists when pg_cron is available');
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)values('a9100000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','purge-91@example.invalid','',now(),'{}','{}',now(),now());
insert into public.organizations(id,legal_name,display_name,status,created_by)values('b9100000-0000-4000-8000-000000000001','Purge Auto Runtime','Purge Auto','ACTIVE','a9100000-0000-4000-8000-000000000001');
insert into public.assistance_model_versions(id,model_key,version,algorithm,configuration,status,effective_from,content_hash,change_reason,created_by)values('d9100000-0000-4000-8000-000000000001','PURGE_TEST_V91',1,'TOKEN_OVERLAP_V1','{"minimum_score_basis_points":1000,"duplicate_score_basis_points":8000,"candidate_limit":10}','ARCHIVED',statement_timestamp()-interval'1 year',repeat('7',64),'Autonomous purge fixture','a9100000-0000-4000-8000-000000000001');
insert into public.assistance_requests(id,organization_id,model_version_id,context_type,status,input_text,input_hash,input_text_expires_at,created_by,created_at)values('c9100000-0000-4000-8000-000000000001','b9100000-0000-4000-8000-000000000001','d9100000-0000-4000-8000-000000000001','CONTEXTUAL_ASSISTANT','COMPLETED','CNIE n° AB 123456',repeat('6',64),statement_timestamp()-interval'1 day','a9100000-0000-4000-8000-000000000001',statement_timestamp()-interval'31 days');
create temporary table purge91(k text primary key,v jsonb);insert into purge91 values('cycle',private.run_assistance_input_purge_cycle(10));
select is((select(v->>'processed')::int from purge91 where k='cycle'),1,'autonomous DB worker processes an expired input');
select ok((select input_text is null and input_text_redacted_at is not null from public.assistance_requests where id='c9100000-0000-4000-8000-000000000001'),'autonomous execution purges retained text');
select is((private.run_assistance_input_purge_cycle(10)->>'processed')::int,0,'autonomous cycle replay is idempotent');
insert into public.assistance_requests(id,organization_id,model_version_id,context_type,status,input_text,input_hash,input_text_expires_at,created_by,created_at)values('c9100000-0000-4000-8000-000000000002','b9100000-0000-4000-8000-000000000001','d9100000-0000-4000-8000-000000000001','CONTEXTUAL_ASSISTANT','COMPLETED','Retry sans donnée personnelle',repeat('5',64),statement_timestamp()+interval'30 days','a9100000-0000-4000-8000-000000000001',statement_timestamp());
insert into public.assistance_input_purge_jobs(id,organization_id,request_id,status,attempt_count,lease_token,worker_id,leased_until)values('e9100000-0000-4000-8000-000000000001','b9100000-0000-4000-8000-000000000001','c9100000-0000-4000-8000-000000000002','CLAIMED',1,'f9100000-0000-4000-8000-000000000001','worker-expired',clock_timestamp()-interval'1 second');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select throws_ok($$select public.fail_assistance_input_purge_job('e9100000-0000-4000-8000-000000000001','f9100000-0000-4000-8000-000000000001','worker-expired','expired-lease','TRANSIENT')$$::text,'55000'::text,'ASSISTANCE_PURGE_LEASE_INVALID'::text,'failure rejects an expired lease'::text);
update public.assistance_input_purge_jobs set leased_until=clock_timestamp()+interval'5 minutes'where id='e9100000-0000-4000-8000-000000000001';
insert into purge91 values('failed',public.fail_assistance_input_purge_job('e9100000-0000-4000-8000-000000000001','f9100000-0000-4000-8000-000000000001','worker-expired','valid-failure','TRANSIENT'));
select is((select v->>'status'from purge91 where k='failed'),'FAILED','valid lease schedules bounded retry');
select is(public.fail_assistance_input_purge_job('e9100000-0000-4000-8000-000000000001','f9100000-0000-4000-8000-000000000001','worker-expired','valid-failure','TRANSIENT'),(select v from purge91 where k='failed'),'failure replay is stable before mutable status checks');
select is((select count(*)from public.assistance_input_purge_attempts where job_id='e9100000-0000-4000-8000-000000000001'),1::bigint,'failure replay writes one attempt');
select *from finish();rollback;
